function bstFromPreorder(preorder) {
  const root = new TreeNode(preorder[0]);
  const stack = [root];
  for (let k = 1; k < preorder.length; k++) {
    const node = new TreeNode(preorder[k]);
    let parent = stack[stack.length - 1];
    while (stack.length > 0 && stack[stack.length - 1].val < node.val) parent = stack.pop();
    if (parent.val < node.val) parent.right = node;   // the last smaller node popped
    else parent.left = node;                          // smaller than the top
    stack.push(node);
  }
  return root;
}

