TreeNode bstFromPreorder(int[] preorder) {
    TreeNode root = new TreeNode(preorder[0]);
    Deque<TreeNode> stack = new ArrayDeque<>();
    stack.push(root);
    for (int k = 1; k < preorder.length; k++) {
        TreeNode node = new TreeNode(preorder[k]);
        TreeNode parent = stack.peek();
        while (!stack.isEmpty() && stack.peek().val < node.val) parent = stack.pop();
        if (parent.val < node.val) parent.right = node;   // the last smaller node popped
        else parent.left = node;                          // smaller than the top
        stack.push(node);
    }
    return root;
}

